#[allow(dead_code)]mod target{include!("../hec_alignment13_20261115/atlas/target.rs");include!("target_api631.rs");}
use std::{fs,path::Path};
fn main(){let a:Vec<_>=std::env::args().collect();let qf:[u64;15]=fs::read_to_string("QF.txt").unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect::<Vec<_>>().try_into().unwrap();let pts=target::rational_points(&qf,631);let j=target::QuarticJacobian::with_points(631,qf,pts.clone()).unwrap();let mut count=0;for name in["anchors01","anchors02","anchors03","anchors12","anchors13","anchors23"]{let text=fs::read_to_string(Path::new(&a[1]).join(format!("{name}.stdout"))).unwrap();for line in text.lines().filter(|s|s.starts_with("CALIBRATION x=")){let at=line.find(" pair=").unwrap()+6;let end=at+line[at..].find("]]").unwrap()+2;let ns:Vec<u64>=line[at..end].split(|c:char|!c.is_ascii_digit()).filter(|s|!s.is_empty()).map(|s|s.parse().unwrap()).collect();assert_eq!(ns.len(),6);let p:[u64;3]=ns[..3].try_into().unwrap();let q:[u64;3]=ns[3..].try_into().unwrap();assert!(pts.contains(&p)&&pts.contains(&q)&&p!=q);let x=target::scalar(&j,target::difference(&j,p,q),4);assert_ne!(x,j.zero());assert_eq!(target::scalar(&j,x,59296481),j.zero());assert_ne!(target::scalar(&j,x,59296480),j.zero());count+=1;println!("PAIR_CONTROL case={name} index={count} target_nonzero_prime_order=true wrong_order_rejected=true");}}assert_eq!(count,10);println!("PASS all_decoded_target_pairs_verified={count} no_fiber_rerun=true actual_global_map_or_DLP_verified=false");}
